@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource-variable/arimo";

/* Light (faithful): white page, charcoal ink and hairlines, one loud safety orange, an olive
   grey for quiet text and every button's hover, a denim-blue band with navy accents.
   3px corners on orange buttons, pills for the rest, flat surfaces. */
:root {
  --background: #ffffff;
  --foreground: #25282a;
  --card: #ffffff;
  --card-foreground: #25282a;
  --popover: #ffffff;
  --popover-foreground: #25282a;
  --primary: #e75301;
  --primary-foreground: #ffffff;
  --secondary: #25282a;
  --secondary-foreground: #ffffff;
  --muted: #eeeeec;
  --muted-foreground: #64665c;
  --accent: #507bba;
  --accent-foreground: #ffffff;
  --destructive: #c62f1d;
  --destructive-foreground: #ffffff;
  --border: #25282a;
  --input: #64665c;
  --ring: #e75301;
  --highlight: #212b69;
  --highlight-foreground: #ffffff;
  --glow: #e75301;
  --chart-1: #e75301;
  --chart-2: #507bba;
  --chart-3: #212b69;
  --chart-4: #64665c;
  --chart-5: #ddded3;
  --sidebar: #f5f5f5;
  --sidebar-foreground: #25282a;
  --sidebar-primary: #e75301;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #eeeeec;
  --sidebar-accent-foreground: #25282a;
  --sidebar-border: #25282a;
  --sidebar-ring: #e75301;

  --typeface-body: "Hanken Grotesk Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", "Helvetica Neue", Arial, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  /* rollers only: the Helvetica-style grotesk of the statements and big figures; blocks read
     it with a fallback to --typeface-body, so other themes need not set it */
  --typeface-grotesk: "Arimo Variable", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --radius: 0.1875rem;
  --page-width: 100%;
  --page-gutter: 1.875rem;
  --section-y: 2.5rem;
}

@media (min-width: 48rem) {
  :root {
    --page-gutter: 2.5rem;
    --section-y: 6.875rem;
  }
}

/* Dark (sibling, and the palette of the charcoal bands in light mode): the charcoal becomes
   the page, white ink, the same orange; the olive grey turns into the chip and hover colour;
   hairlines are a soft white. */
.dark {
  --background: #25282a;
  --foreground: #ffffff;
  --card: #2e3234;
  --card-foreground: #ffffff;
  --popover: #2e3234;
  --popover-foreground: #ffffff;
  --primary: #e75301;
  --primary-foreground: #ffffff;
  --secondary: #64665c;
  --secondary-foreground: #ffffff;
  --muted: #363a3d;
  --muted-foreground: #8f9186;
  --accent: #46699f;
  --accent-foreground: #ffffff;
  --destructive: #e2533f;
  --destructive-foreground: #ffffff;
  --border: rgb(255 255 255 / 0.55);
  --input: #8f9186;
  --ring: #e75301;
  --highlight: #1c2459;
  --highlight-foreground: #ffffff;
  --glow: #e75301;
  --chart-1: #e75301;
  --chart-2: #6f95cc;
  --chart-3: #9aa6e6;
  --chart-4: #8f9186;
  --chart-5: #ddded3;
  --sidebar: #2e3234;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #e75301;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #363a3d;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: rgb(255 255 255 / 0.55);
  --sidebar-ring: #e75301;
}
